head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.vScrenID = "ULDSTF05806.xml";
scwin.vScrenTpCD = "";
scwin.vBzProcsNo = "";
scwin.vIsurCd = "";
scwin.trsIdx; // insert, update 구분
scwin.rowPos;
scwin.vISU_ENG_NM = "";
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.stf.InfoMenuID());
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    //arrPar[1] = getObjectValue(txb_SearchNm);	// 명칭값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = arrPar[0].SPOT_ISU_TRD_MKT_TP_CD;
        scwin.vIsurCd = arrPar[0].ISUR_CD;
        scwin.fn_initMktPerComponent(scwin.vSPOT_ISU_TRD_MKT_TP_CD);
        scwin.fn_initItem();
        scwin.fn_isubook_read_sync();
        scwin.fn_list_sync();
    }
};
scwin.fn_GetParRsn = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = "1";
    arrPar[1] = "05";
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParRsn = function(arrPar) {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    /*ORG SRC: dts_Mst.NameString(1, "DELIST_RSN_CD") = (arrPar.length >= 1 ? arrPar[0] : "");*/
    X = (arrPar.length >= 1 ? arrPar[0] : "");
    txb_DELIST_RSN_DSC.Text = (arrPar.length >= 2 ? arrPar[1] : "");
    txb_GRND_REGUL_NM.setValue((arrPar.length >= 3 ? arrPar[2] : ""));
};


/**
 * 시장을 구분해서 콤포넌트 보여주기
 */
scwin.fn_initMktPerComponent = function(pMkt) {
    if (pMkt == '1') {
        img_DELIST_RSN_DSC.src = "../img/btn_search.gif";
        img_DELIST_RSN_DSC.setDisabled(false);
        txb_DELIST_RSN_DSC.setReadOnly(true);
        txb_DELIST_RSN_DSC.style.backgroundColor = '#b9d4f7';
        label_2.style.top = 7;
        label_1.style.top = 7;
        edt_DELIST_DD.style.top = 7;
        img_DELIST_DD.style.top = 7;
        lb_LIST_SHRS.style.top = 7;
        edt_LIST_SHRS.style.top = 7;
        $c.stf.showObj(label_3, true);
        $c.stf.showObj(edt_DELIST_ADVNOTI_STRT_DD, true);
        $c.stf.showObj(img_DELIST_ADVNOTI_STRT_DD, true);
        $c.stf.showObj(label_9, true);
        $c.stf.showObj(edt_DELIST_ADVNOTI_END_DD, true);
        $c.stf.showObj(img_DELIST_ADVNOTI_END_DD, true);
        $c.stf.showObj(lbl_ArrantrdPermiPd, true);
        $c.stf.showObj(edt_ARRANTRD_MKTACT_ENFORCE_DD, true);
        $c.stf.showObj(img_ARRANTRD_MKTACT_ENFORCE_DD, true);
        $c.stf.showObj(lbl_Tilde, true);
        $c.stf.showObj(edt_ARRANTRD_END_DD, true);
        $c.stf.showObj(img_ARRANTRD_END_DD, true);
    } else if (pMkt == '2') {
        img_DELIST_RSN_DSC.src = "../img/btn_search_d.gif";
        img_DELIST_RSN_DSC.setDisabled(true);
        txb_DELIST_RSN_DSC.setReadOnly(false);
        txb_DELIST_RSN_DSC.style.backgroundColor = '#ffffff';
        $c.stf.showObj(label_3, false);
        $c.stf.showObj(edt_DELIST_ADVNOTI_STRT_DD, false);
        $c.stf.showObj(img_DELIST_ADVNOTI_STRT_DD, false);
        $c.stf.showObj(label_9, false);
        $c.stf.showObj(edt_DELIST_ADVNOTI_END_DD, false);
        $c.stf.showObj(img_DELIST_ADVNOTI_END_DD, false);
        $c.stf.showObj(lbl_ArrantrdPermiPd, false);
        $c.stf.showObj(edt_ARRANTRD_MKTACT_ENFORCE_DD, false);
        $c.stf.showObj(img_ARRANTRD_MKTACT_ENFORCE_DD, false);
        $c.stf.showObj(lbl_Tilde, false);
        $c.stf.showObj(edt_ARRANTRD_END_DD, false);
        $c.stf.showObj(img_ARRANTRD_END_DD, false);
        label_2.style.top = 56;
        label_1.style.top = 56;
        edt_DELIST_DD.style.top = 56;
        img_DELIST_DD.style.top = 56;
        lb_LIST_SHRS.style.top = 56;
        edt_LIST_SHRS.style.top = 56;
    }
};
scwin.fn_initItem = function() {
    buttonSet.setInsertStatus();
    dts_Isu.removeAll();
    dts_Isu.insertRow();
    dts_Mst.removeAll();
    dts_Mst.insertRow();
    scwin.vBzProcsNo = ""; //초기화 

};


//신주인수권증권/증서수 조회
scwin.fn_isubook_read_sync = function() {
    var url = "/Delisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchTotstkcnt&inputMessageId=DELISTING_INOUT" + "&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
    dts_Mst.DataID = encodeURI(url);
    dts_Mst.reset();
};


//품목코드선택시 리스트 조회
scwin.fn_list_sync = function() {
    if (scwin.fr_SecuGrpId == SECUGRP_ID_SW) {
        $c.stf.setObjectValue(lb_LIST_SHRS, '상장증권수');
        $c.cm.setColumnProp(grd_List, "LIST_SHRS", "Name", '상장증권수');
    } else if (scwin.fr_SecuGrpId == SECUGRP_ID_SR) {
        $c.stf.setObjectValue(lb_LIST_SHRS, '상장증서수');
        $c.cm.setColumnProp(grd_List, "LIST_SHRS", "Name", '상장증서수');
    }
    var url = "/Delisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchlist&inputMessageId=DELISTING_INOUT" + "&ISU_CD=" + $c.stf.getObjectValue(txb_ISU_CD);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};


//그리드  더블 클릭시 조회
scwin.fn_read_sync = function(row) {
    scwin.vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
    var url = "/Delisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchlistDbDetail&inputMessageId=DELISTING_INOUT" + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Mst.DataID = encodeURI(url);
    dts_Mst.reset();
};
scwin.fn_getListBzTpCd = function() {
    var VListBzTpCd = "";
    if (scwin.fr_SecuGrpId == SECUGRP_ID_SW) {
        VListBzTpCd = LIST_BZ_TP_CD_203;
    } else if (scwin.fr_SecuGrpId == SECUGRP_ID_SR) {
        VListBzTpCd = LIST_BZ_TP_CD_204;
    }
    return VListBzTpCd;
};
scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목코드]를 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_DELIST_DD) == "") {
        $c.win.alert("[상장폐지일]을 입력하세요.");
        edt_DELIST_DD.focus();
        return false;
    }
    if ($c.ut.cGetToday("yyyymmdd") >= $c.stf.getObjectValue(edt_DELIST_DD)) {
        $c.win.alert("[상장폐지일]을 현재일이후로 입력하세요.");
        edt_DELIST_DD.focus();
        return false;
    }
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "1") {
        if (dts_Mst.getCellData(1, "DELIST_RSN_CD") == "") {
            $c.win.alert("[상장폐지사유]를 선택하세요.");
            txb_DELIST_RSN_DSC.focus();
            return false;
        }

    } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "2") {
        if (txb_DELIST_RSN_DSC.Text == "") {
            $c.win.alert("[상장폐지사유]를 입력하세요.");
            txb_DELIST_RSN_DSC.focus();
            return false;
        }
        if (!$c.stf.checkMaxLength(txb_DELIST_RSN_DSC, 2000, "상장폐지사유")) return false;
    }
    if ($c.stf.getObjectValue(txb_GRND_REGUL_NM) == "") {
        $c.win.alert("[근거규정]을 입력하세요.");
        txb_GRND_REGUL_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_GRND_REGUL_NM, 200, "근거규정")) return false;
    if (!$c.lc.fn_check_bz_doubleinput(dts_BZ_CHECK, $c.stf.getObjectValue(txb_ISU_CD), $c.stf.getObjectValue(edt_DELIST_DD), dts_Mst.getCellData(1, "BZ_PROCS_NO"), scwin.fn_getListBzTpCd())) {
        return false;
    }
    return true;
};
scwin.fn_save = function() {
    scwin.trsIdx = TRS_IDX_INSERT;
    if (!scwin.fn_CheckForm()) return;
    if (!$c.lc.fn_isProcess('I')) return;
    scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
    if (scwin.vBzProcsNo.length != 14) {
        $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
    } else {
        dts_Mst.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        //alert('[dts_Mst]'+dts_Mst.text);
        scwin.fn_trs();
    }
};
scwin.fn_update = function() {
    scwin.trsIdx = TRS_IDX_UPDATE;
    if (!scwin.fn_CheckForm()) return;
    if (!$c.lc.fn_isProcess('U')) return;
    scwin.fn_trs();
};
scwin.fn_delete = function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    scwin.fn_trs();
};
scwin.fn_trs = function() {
    if (scwin.trsIdx == '1') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.trsIdx == '2') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.trsIdx == '3') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    for (var i = 1; i <= dts_Isu.getTotalRow(); i++) {
        dts_Isu.setCellData(i, "BZ_PROCS_NO", scwin.vBzProcsNo);
        dts_Isu.setCellData(i, "ISU_CD", $c.stf.getObjectValue(txb_ISU_CD));
    }

    // 종목별기준으로 처리함
    // 1 : 종목별 , 2 : 법인별
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "MKTACT_APPL_OBJ_TP_CD", "1");
    dts_Mst.setCellData(1, "ISUR_CD", scwin.vIsurCd);

    //alert(dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "CODE") + "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "NAME")+ "\n" + dts_Rsn.NameString(cmb_Rsn_Cd.index + 1, "REGL")) ;

    trs_Save.Action = $c.lc.fn_encodeNSession("/Delisting.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveDelList");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I: dtsParm1= dts_Mst , I:dtsParm2= dts_Isu)";
    trs_Save.Parameters = "TRS_IDX=" + scwin.trsIdx + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",COUNT=2" + ",LIST_BZ_TP_CD=" + scwin.fn_getListBzTpCd() + ",DIV_IDX[0]=" + DIV_IDX_DELLIST_MST + ",DIV_IDX[1]=" + DIV_IDX_DELLIST_DTL;
    trs_Save.Post();
};
scwin.fn_dscl = async function() {
    if ($c.cp.isModified(dts_Mst)) {
        $c.win.alert($c.stf.getMessageParam("MSG-0022", ""));
        return;
    }
    var OldGet = fn_GetPar;
    var OldSet = fn_SetPar;
    if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "1") {
        // 유가경우
        fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
            if (scwin.fr_SecuGrpId == SECUGRP_ID_SW) {
                arr[0] = "68913";
            } else if (scwin.fr_SecuGrpId == SECUGRP_ID_SR) {
                arr[0] = "68917";
            }
            arr[1] = scwin.vBzProcsNo;
            arr[2] = scwin.vIsurCd;
            arr[3] = scwin.vSPOT_ISU_TRD_MKT_TP_CD;
            arr[4] = "";
            arr[5] = '';

            //CopyDataSet( dts_Isu , param_dts_isu) ;
            $c.stf.CopyDataSet(dts_Mst, param_dts_mst);
            return arr.length;
        };
    } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD == "2") {
        // 코스닥인경우
        fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_rel_eng, param_dts_dtl_all_eng) {
            if (scwin.fr_SecuGrpId == SECUGRP_ID_SW) {
                arr[0] = "70925";
            } else if (scwin.fr_SecuGrpId == SECUGRP_ID_SR) {
                arr[0] = "70930";
            }
            arr[1] = scwin.vBzProcsNo;
            arr[2] = scwin.vIsurCd;
            arr[3] = scwin.vSPOT_ISU_TRD_MKT_TP_CD;
            $c.stf.CopyDataSet(dts_Mst, param_dts_mst);
            $c.stf.CopyDataSet(dts_Mst_Eng, param_dts_mst_eng);
            return arr.length;
        };
    }
    fn_SetPar = function(arr) {

    };
    var wth = 730 + 5;
    var hgt = 785 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    fn_GetPar = OldGet;
    fn_SetPar = OldSet;
};
scwin.fn_drft = function() {
    var OldGet = fn_GetPar;
    fn_GetPar = function(arr) {
        arr[0] = dts_List.getCellData(1, "BZ_PROCS_NO");
        return arr.length;
    };
    $c.lc.fn_PopFindDraft();
    fn_GetPar = OldGet;
};


//function fn_makt() { }


scwin.btn_Search_onclick = function() {
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return;
    } else {
        scwin.fn_initItem();
        scwin.fn_isubook_read_sync();
        scwin.fn_list_sync();
    }
};
scwin.img_ISU_NM_onclick = function() {
    fn_GetPar = fn_GetParIsuCd;
    fn_SetPar = fn_SetParIsuCd;
    $c.lc.fn_PopFindIsu(scwin.fr_SecuGrpId);
};
scwin.img_DELIST_RSN_DSC_onclick = function() {
    fn_GetPar = fn_GetParRsn;
    fn_SetPar = fn_SetParRsn;
    $c.lc.fn_PopFindClssLstRsnCd(RSNCD_DELIST);
};
scwin.img_DELIST_DD_onclick = function() {
    popUpCalendar2(edt_DELIST_DD);
};
scwin.grd_List_OnClick = function(row, colid) {
    scwin.fn_read_sync(row);
};
scwin.dts_BZ_CHECK_OnLoadError = function() {
    $c.stf.alert_error(dts_BZ_CHECK);
};
scwin.dts_Mst_OnLoadError = function() {
    $c.stf.alert_error(dts_Mst);
};
scwin.dts_Isu_OnLoadError = function() {
    $c.stf.alert_error(dts_Isu);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    if (scwin.vBzProcsNo == "") {
        buttonSet.setInsertStatus();
    } else {
        if ($c.ut.cGetToday("yyyymmdd") <= $c.stf.getObjectValue(edt_DELIST_DD)) {
            buttonSet.setUpdateStatus();
        } else {
            buttonSet.setErrorStatus();
        }
    }

    //영문공시용 
    $c.stf.CopyDataSet(dts_Mst, dts_Mst_Eng);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    if (scwin.vBzProcsNo == "") {
        buttonSet.setInsertStatus();
    }
};
scwin.trs_Save_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_initItem();
    scwin.fn_list_sync();
    if (buttonSet.status != "D") {
        // 삭제처리의 응답인 경우
        scwin.fn_read_sync(dts_List.getTotalRow());
    }
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    $c.cm.PanelToGroupBox(panel_Item);

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성
    buttonSet.setDrftInfo(btn_Drft, fn_drft); // 기안

    buttonSet.setInsertStatus();
    dts_Isu.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DELISTING_ISU_INOUT";
    dts_Isu.reset();
    scwin.fn_initMktPerComponent(js_market);
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_DELIST_ADVNOTI_STRT_DD_onclick = function() {
    popUpCalendar2(edt_DELIST_ADVNOTI_STRT_DD);
};
scwin.img_DELIST_ADVNOTI_END_DD_onclick = function() {
    popUpCalendar2(edt_DELIST_ADVNOTI_END_DD);
};
scwin.img_ARRANTRD_END_DD_onclick = function() {
